import { randomFillSync } from "node:crypto";

/**
 * Prefixed ULID identifiers (LLD §1 conventions, FR-SES-01: IDs are generated by the controller, never by providers).
 * `sess_`, `run_`, `evt_`, `art_` are fixed by the brief; the others are Proposed in LLD §1, except `pbd_`
 * (provider_binding, T2.4), which is Proposed here and not yet listed in LLD §1; `gcm_` (git_commit) is Proposed in LLD §1 and `gps_` (git_push) is Proposed in T9.3;
 * `prv_` (project_revision) is Proposed in LLD §1, and `prd_` (project_revision_decision) and `pev_` (project_event) are
 * Proposed in T9.9 (ADR-0030); `inc_` (inner_call) is Proposed in LLD §13.3 (T11.1).
 */
export const ID_PREFIXES = [
  "sess",
  "run",
  "evt",
  "art",
  "dec",
  "ckp",
  "rte",
  "apv",
  "adv",
  "use",
  "pbd",
  "gcm",
  "gps",
  "prv",
  "prd",
  "pev",
  "inc",
  "rag",
  "rrq",
  "que",
  "pwe",
  "cpe",
] as const;
export type IdPrefix = (typeof ID_PREFIXES)[number];

const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"; // Crockford base32
const TIME_LEN = 10;
const RAND_LEN = 16;
const MAX_TIME = 2 ** 48 - 1;

export interface IdGeneratorOptions {
  /** Injectable clock, milliseconds since the epoch. Default `Date.now`. */
  now?: () => number;
  /** Injectable entropy source: must return `n` random values in 0..31. Default: crypto. */
  randomDigits?: (n: number) => number[];
}

function cryptoDigits(n: number): number[] {
  const buf = new Uint8Array(n);
  randomFillSync(buf);
  return Array.from(buf, (b) => b & 31);
}

function encodeTime(ms: number): string {
  if (!Number.isInteger(ms) || ms < 0 || ms > MAX_TIME) throw new RangeError(`timestamp out of ULID range: ${ms}`);
  let out = "";
  let rest = ms;
  for (let i = 0; i < TIME_LEN; i++) {
    out = ALPHABET[rest % 32] + out;
    rest = Math.floor(rest / 32);
  }
  return out;
}

export interface IdGenerator {
  /** Bare 26-character ULID, strictly increasing across calls on this generator. */
  ulid(): string;
  /** `<prefix>_<ULID>`. */
  id(prefix: IdPrefix): string;
}

/**
 * Create a monotonic ULID generator. Within one millisecond (or if the clock moves backwards) the previous random
 * component is incremented, so output is strictly increasing and lexically sortable per generator.
 */
export function createIdGenerator(options: IdGeneratorOptions = {}): IdGenerator {
  const now = options.now ?? Date.now;
  const randomDigits = options.randomDigits ?? cryptoDigits;
  let lastTime = -1;
  let lastRand: number[] = [];

  const ulid = (): string => {
    let t = now();
    if (t <= lastTime) {
      // Same millisecond or clock regression: keep the last time and increment the random part.
      t = lastTime;
      const next = lastRand.slice();
      let i = RAND_LEN - 1;
      while (i >= 0 && next[i] === 31) {
        next[i] = 0;
        i--;
      }
      if (i < 0) throw new RangeError("ULID random component overflow within one millisecond");
      next[i] = (next[i] as number) + 1;
      lastRand = next;
    } else {
      lastTime = t;
      lastRand = randomDigits(RAND_LEN);
    }
    return encodeTime(t) + lastRand.map((d) => ALPHABET[d]).join("");
  };

  return { ulid, id: (prefix) => `${prefix}_${ulid()}` };
}

const ULID_RE = /^[0-9A-HJKMNP-TV-Z]{26}$/;

export function isPrefixedId(value: string, prefix: IdPrefix): boolean {
  return value.startsWith(`${prefix}_`) && ULID_RE.test(value.slice(prefix.length + 1));
}

/** Process-wide default generator. */
export const defaultIds: IdGenerator = createIdGenerator();
